39	export type PaymentsClientOptions = {
40	  apiKey: string;
41	  baseUrl?: string;
42	};
43	
44	export class PaymentsClient {
45	  readonly #apiKey: string;
46	  readonly #baseUrl: string;
47	
48	  constructor({ apiKey, baseUrl = "https://api.example.com/v1" }: PaymentsClientOptions) {
49	    this.#apiKey = apiKey;
50	    this.#baseUrl = baseUrl;
51	  }
52	
53	  createPayment(input: CreatePaymentInput) {
54	    return this.#request<Payment>("POST", "/payments", input);
55	  }
56	
57	  getPayment(id: string) {
58	    return this.#request<Payment>("GET", `/payments/${encodeURIComponent(id)}`);
59	  }
60	
61	  async listPayments(filter: { status?: PaymentStatus } = {}) {
62	    const query = filter.status ? `?status=${filter.status}` : "";
63	    const { data } = await this.#request<{ data: Payment[] }>("GET", `/payments${query}`);
64	    return data;
65	  }
66	
67	  refundPayment(id: string, input: RefundInput = {}) {
68	    return this.#request<Payment>("POST", `/payments/${encodeURIComponent(id)}/refund`, input);
69	  }
70	
71	  cancelPayment(id: string) {
72	    return this.#request<Payment>("POST", `/payments/${encodeURIComponent(id)}/cancel`);
73	  }
74	
75	  async #request<T>(method: string, path: string, body?: unknown): Promise<T> {
76	    const response = await fetch(`${this.#baseUrl}${path}`, {
77	      method,
78	      headers: {
79	        Authorization: `Bearer ${this.#apiKey}`,
80	        ...(body !== undefined && { "Content-Type": "application/json" }),
81	      },
82	      body: body !== undefined ? JSON.stringify(body) : undefined,
83	    });
84	
85	    if (!response.ok) {
86	      const payload = (await response.json().catch(() => null)) as {
87	        error?: { code?: string; message?: string };
88	      } | null;
89	      throw new PaymentsApiError(
90	        response.status,
91	        payload?.error?.code ?? "unknown_error",
92	        payload?.error?.message ?? response.statusText,
93	      );
94	    }
95	
96	    return (await response.json()) as T;
97	  }
98	}
