27	async function expectApiError(
28	  promise: Promise<unknown>,
29	  expected: { status: number; code: string; message?: string },
30	) {
31	  const error = await promise.then(
32	    () => {
33	      throw new Error("expected the request to be rejected");
34	    },
35	    (e: unknown) => e,
36	  );
37	  expect(error).toBeInstanceOf(PaymentsApiError);
38	  const apiError = error as PaymentsApiError;
39	  expect(apiError.status).toBe(expected.status);
40	  expect(apiError.code).toBe(expected.code);
41	  if (expected.message !== undefined) {
42	    expect(apiError.message).toBe(expected.message);
43	  }
44	}
